const c16_t *Payload_SCs_select(int RBs, int M, int payload, bool ZC_Ones) {
  if(M != 1 && M != 2 && M != 4) AssertFatal(1==0,"Unknown M %d",M);
  if(payload > M-((M == 1) ? 0 : 1)) AssertFatal(1==0,"Payload value higher than M");
  switch (M) {
    case 1:
      switch (RBs) {
        case 1:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M1_0 : Payload_SCs_Ones_1RBs_M1_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M1_1 : Payload_SCs_Ones_1RBs_M1_1;
          }
        case 6:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M1_0 : Payload_SCs_Ones_6RBs_M1_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M1_1 : Payload_SCs_Ones_6RBs_M1_1;
          }
        case 25:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M1_0 : Payload_SCs_Ones_25RBs_M1_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M1_1 : Payload_SCs_Ones_25RBs_M1_1;
          }
        case 50:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M1_0 : Payload_SCs_Ones_50RBs_M1_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M1_1 : Payload_SCs_Ones_50RBs_M1_1;
          }
        case 100:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M1_0 : Payload_SCs_Ones_100RBs_M1_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M1_1 : Payload_SCs_Ones_100RBs_M1_1;
          }
        default:
          AssertFatal(1==0,"Unknown N_PRB");
      }
    case 2:
      switch (RBs) {
        case 1:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M2_0 : Payload_SCs_Ones_1RBs_M2_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M2_1 : Payload_SCs_Ones_1RBs_M2_1;
          }
        case 6:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M2_0 : Payload_SCs_Ones_6RBs_M2_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M2_1 : Payload_SCs_Ones_6RBs_M2_1;
          }
        case 25:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M2_0 : Payload_SCs_Ones_25RBs_M2_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M2_1 : Payload_SCs_Ones_25RBs_M2_1;
          }
        case 50:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M2_0 : Payload_SCs_Ones_50RBs_M2_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M2_1 : Payload_SCs_Ones_50RBs_M2_1;
          }
        case 100:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M2_0 : Payload_SCs_Ones_100RBs_M2_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M2_1 : Payload_SCs_Ones_100RBs_M2_1;
          }
        default:
          AssertFatal(1==0,"Unknown N_PRB");
      }
    case 4:
      switch (RBs) {
        case 1:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M4_0 : Payload_SCs_Ones_1RBs_M4_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M4_1 : Payload_SCs_Ones_1RBs_M4_1;
            case 2:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M4_2 : Payload_SCs_Ones_1RBs_M4_2;
            case 3:
              return ZC_Ones ? Payload_SCs_ZC_1RBs_M4_3 : Payload_SCs_Ones_1RBs_M4_3;
          }
        case 6:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M4_0 : Payload_SCs_Ones_6RBs_M4_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M4_1 : Payload_SCs_Ones_6RBs_M4_1;
            case 2:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M4_2 : Payload_SCs_Ones_6RBs_M4_2;
            case 3:
              return ZC_Ones ? Payload_SCs_ZC_6RBs_M4_3 : Payload_SCs_Ones_6RBs_M4_3;
          }
        case 25:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M4_0 : Payload_SCs_Ones_25RBs_M4_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M4_1 : Payload_SCs_Ones_25RBs_M4_1;
            case 2:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M4_2 : Payload_SCs_Ones_25RBs_M4_2;
            case 3:
              return ZC_Ones ? Payload_SCs_ZC_25RBs_M4_3 : Payload_SCs_Ones_25RBs_M4_3;
          }
        case 50:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M4_0 : Payload_SCs_Ones_50RBs_M4_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M4_1 : Payload_SCs_Ones_50RBs_M4_1;
            case 2:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M4_2 : Payload_SCs_Ones_50RBs_M4_2;
            case 3:
              return ZC_Ones ? Payload_SCs_ZC_50RBs_M4_3 : Payload_SCs_Ones_50RBs_M4_3;
          }
        case 100:
          switch (payload) {
            case 0:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M4_0 : Payload_SCs_Ones_100RBs_M4_0;
            case 1:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M4_1 : Payload_SCs_Ones_100RBs_M4_1;
            case 2:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M4_2 : Payload_SCs_Ones_100RBs_M4_2;
            case 3:
              return ZC_Ones ? Payload_SCs_ZC_100RBs_M4_3 : Payload_SCs_Ones_100RBs_M4_3;
          }
        default:
          AssertFatal(1==0,"Unknown N_PRB");
      }
    default:
      AssertFatal(1==0,"Unknown M");
  }
}

